import 'reflect-metadata';
import dotenv from 'dotenv';
import { DataSource } from 'typeorm';
import {
  AuthSession,
  Organization,
  OrganizationMembership,
  Program,
  User,
  Affiliate,
  ProgramAffiliate,
  AffiliateApplication,
  TrackingLink,
  Click,
  Attribution,
  ApiKey,
  IdempotencyKey,
  Conversion,
  CommissionRule,
  Commission,
  LedgerAccount,
  LedgerTransaction,
  LedgerEntry,
  FraudReview,
  FraudSettings,
  FraudAssessment,
  FraudSignal,
  AffiliateTrustHistory,
  FraudMetricRollup,
  PayoutBatch,
  PayoutItem,
  WebhookEndpoint,
  WebhookDelivery,
  AuditLog,
  PublicKey,
  Integration,
  OrganizationIntegration,
  IntegrationCredential,
  IntegrationEvent,
  IntegrationOAuthState,
} from './schema';
import {
  RoleDefinition,
  PermissionDefinition,
  RolePermission,
  OrganizationPolicy,
  OrganizationInvitation,
} from './schema-rbac';

dotenv.config();

const databaseUrl = process.env.DATABASE_URL;
const databaseHost = process.env.DATABASE_HOST || process.env.PLANETSCALE_DB_HOST || 'localhost';
const databasePort = parseInt(process.env.DATABASE_PORT || '3306', 10);
const databaseUsername = process.env.DATABASE_USER || process.env.PLANETSCALE_DB_USERNAME || 'root';
const databasePassword = process.env.DATABASE_PASSWORD || process.env.PLANETSCALE_DB_PASSWORD || '';
const databaseName = process.env.DATABASE_NAME || process.env.PLANETSCALE_DB || 'partner_db';
const databaseSsl =
  process.env.DATABASE_SSL === 'true' ||
  Boolean(process.env.DATABASE_URL || process.env.PLANETSCALE_DB_HOST)
    ? { rejectUnauthorized: true }
    : undefined;

export const AppDataSource = new DataSource({
  type: 'mysql',
  ...(databaseUrl
    ? { url: databaseUrl }
    : {
        host: databaseHost,
        port: databasePort,
        username: databaseUsername,
        password: databasePassword,
        database: databaseName,
      }),
  ssl: databaseSsl,
  synchronize: true,
  logging: false,
  entities: [
    User,
    Organization,
    OrganizationMembership,
    AuthSession,
    Program,
    Affiliate,
    ProgramAffiliate,
    AffiliateApplication,
    TrackingLink,
    Click,
    Attribution,
    ApiKey,
    IdempotencyKey,
    Conversion,
    CommissionRule,
    Commission,
    LedgerAccount,
    LedgerTransaction,
    LedgerEntry,
    FraudReview,
    FraudSettings,
    FraudAssessment,
    FraudSignal,
    AffiliateTrustHistory,
    FraudMetricRollup,
    PayoutBatch,
    PayoutItem,
    WebhookEndpoint,
    WebhookDelivery,
    AuditLog,
    PublicKey,
    Integration,
    OrganizationIntegration,
    IntegrationCredential,
    IntegrationEvent,
    IntegrationOAuthState,
    RoleDefinition,
    PermissionDefinition,
    RolePermission,
    OrganizationPolicy,
    OrganizationInvitation,
  ],
  migrations: ['src/database/migrations/*.ts'],
  migrationsRun: false,
});

export async function initializeDataSource() {
  if (!AppDataSource.isInitialized) {
    await AppDataSource.initialize();
  }

  return AppDataSource;
}
